code: x.level,
sub: x.ready ? x.name : 'En preparación',
on,
off,
aria: x.level + ', ' + x.name + (x.ready ? '' : ', en preparación'),
subColor: on ? '#FFFFFF' : off ? '#9AA1B5' : '#5A6382',
