const self = s.skippedSelf || !st.length ? null : { comp: selfOf(st, s.yes, 'comp'), prod: selfOf(st, s.yes, 'prod') };
const comp = asked.length ? compOf(list, asked, s.answers) : self ? self.comp : 'A1';
const prod = skipProd || !s.bench ? below(comp) : s.bench;
const placed = C.placed(comp, prod);
