ms.reduce((a, x) => { ends.push((a + x) / standIn); return a + x; }, 0);
const lineAt = (f) => { for (let n = 0; n < ends.length; n++) if (f < ends[n]) return n; return ends.length - 1; };
const snd = window.gnSound;
