const where = app.session || C.parse(sid) || {};
const day = app.day || null;
const grammar = (day && day.grammar) || null;
const cmp = (grammar && grammar.compare) || {};
const points = list(grammar && grammar.points).filter((p) => typeof p === 'object');
const forms = list(cmp.forms).filter((f) => typeof f === 'object').map((f) => ({
form: C.plain(text(f.form)),
tag: C.plain(text(f.tag)),
hasTag: !!text(f.tag),
tagBg: TAGS[f.mark] || '#E8ECFB',
down: f.mark === 'down',
up: f.mark === 'up',
dot: f.mark !== 'down' && f.mark !== 'up',
segs: segs(C, f.gn),
hasGn: !!text(f.gn),
es: text(f.es),
hasEs: !!text(f.es),
}));
const it = cmp.check && typeof cmp.check === 'object' && Array.isArray(cmp.check.options) && cmp.check.options.length ? cmp.check : null;
const options = it ? it.options.map((o) => C.plain(text(o))) : [];
const key = it ? it.id || sid + '.c' : '';
const pick = s.for === key ? s.pick : null;
const answered = pick !== null && pick >= 0 && pick < options.length;
const right = answered && pick + 1 === it.answer;
const opts = options.map((label, i) => {
let look = { border: '2px solid #1B2440', bg: '#FFFFFF', shadow: '0 3px 0 #1B2440', color: '#1B2440' };
if (answered) {
if (i + 1 === it.answer) look = { border: '2.5px solid #0B7A6B', bg: '#E0F3EF', shadow: 'none', color: '#1B2440' };
else if (i === pick) look = { border: '2.5px solid #C7361E', bg: '#FDEBE6', shadow: 'none', color: '#1B2440' };
else look = { border: '2px solid #DDE1EC', bg: '#FFFFFF', shadow: 'none', color: '#5A6382' };
}
const isRight = answered && i + 1 === it.answer;
const isBad = answered && i === pick && !isRight;
return Object.assign({
label,
on: pick === i,
right: isRight,
bad: isBad,
aria: label + (isRight ? ', respuesta correcta' : isBad ? ', tu respuesta, incorrecta' : ''),
pick: () => this.setState({ pick: i, for: key }),
}, look);
});
const why = answered ? text(Array.isArray(it.why) ? it.why[pick] : '') || text(it.explain) : '';
