/* a part whose questions are not written yet has no clock: its "En preparación" stays put */
const timed = (s.view === 'reading' && M.has.P1) || (s.view === 'mediation' && M.has.P3) || (s.view === 'writing' && s.stage4 === 'write' && M.has.P4);
