const at = C.now();
const result = { level: M.level, parts, apto: r.apto, comprension: r.comprension, groupC: r.groupC, groupP: r.groupP, mode: r.mode, at, recheck: C.addDays(C.today(at), 2), done: KEYS.slice(), a: s.answers, picks: s.picks, text: normText(s.text), take: s.take, rate: s.rate, used: s.used, started: s.started };
